use serde::Serialize;

#[derive(Debug, Clone, Serialize)]
pub enum ContentBlock {
    Paragraph {
        children: Vec<InlineNode>,
    },

    Heading {
        level: u8,
        children: Vec<InlineNode>,
    },

    Image {
        url: String,
        alt: Option<String>,
    },

    CodeBlock {
        language: Option<String>,
        code: String,
    },

    List {
        ordered: bool,
        items: Vec<ListItem>,
    },

    Table {
        rows: Vec<TableRow>,
    },

    Quote {
        children: Vec<InlineNode>,
    },

    Divider,
}

#[derive(Debug, Clone, Serialize)]
pub enum InlineNode {
    Text {
        text: String,
    },

    Bold {
        children: Vec<InlineNode>,
    },

    Italic {
        children: Vec<InlineNode>,
    },

    Link {
        url: String,
        children: Vec<InlineNode>,
    },

    InlineCode {
        text: String,
    },

    Break,
}

#[derive(Debug, Clone, Serialize)]
pub enum ListItem {
    Item {
        children: Vec<InlineNode>,
    },
}

#[derive(Debug, Clone, Serialize)]
pub enum TableRow {
    Row {
        cells: Vec<TableCell>,
    },
}

#[derive(Debug, Clone, Serialize)]
pub enum TableCell {
    Cell {
        children: Vec<InlineNode>,
    },
}

