use crate::models::articles::{ContentBlock, InlineNode, ListItem, TableRow, TableCell};
use scraper::{Html, Node, Selector};
use scraper::node::NodeRef;

/// Entrypoint function that parses a fragment of HTML into a list of structured ContentBlocks.
pub fn parse_html(html: &str) -> Vec<ContentBlock> {
    let html_dom = Html::parse_fragment(html);
    let body_selector = Selector::parse("body").unwrap();

    if let Some(body) = html_dom.select(&body_selector).next() {
        parse_block_nodes(body.children())
    } else {
        Vec::new()
    }
}

/// Checks if an element tag corresponds to a block-level content wrapper.
fn is_block_element(name: &str) -> bool {
    matches!(
        name,
        "p"
            | "h1"
            | "h2"
            | "h3"
            | "h4"
            | "h5"
            | "h6"
            | "img"
            | "ul"
            | "ol"
            | "li"
            | "table"
            | "tr"
            | "td"
            | "th"
            | "blockquote"
            | "hr"
            | "pre"
            | "div"
            | "section"
            | "article"
            | "header"
            | "footer"
            | "aside"
            | "nav"
    )
}

/// Recursively find all `<tr>` elements under a table node (supporting `<thead>`, `<tbody>`, etc.).
fn find_trs<'a>(node: NodeRef<'a, Node>, trs: &mut Vec<NodeRef<'a, Node>>) {
    for child in node.children() {
        if let Node::Element(el) = child.value() {
            if el.name() == "tr" {
                trs.push(child);
            } else if el.name() == "thead" || el.name() == "tbody" || el.name() == "tfoot" {
                find_trs(child, trs);
            }
        }
    }
}

/// Extract programming language names from standard code block classes.
fn extract_language(class_str: &str) -> Option<String> {
    for part in class_str.split_whitespace() {
        if let Some(lang) = part.strip_prefix("language-") {
            return Some(lang.to_string());
        }
        if let Some(lang) = part.strip_prefix("lang-") {
            return Some(lang.to_string());
        }
        if part != "highlight"
            && part != "js-code-highlight"
            && part != "code-highlight"
            && part != "highlight__panel"
            && part != "js-actions-panel"
            && part != "js-fullscreen-code-action"
        {
            return Some(part.to_string());
        }
    }
    None
}

/// Collect all text nodes under a subtree as a flat string.
fn collect_text(node: NodeRef<Node>) -> String {
    let mut text = String::new();
    collect_text_recursive(node, &mut text);
    text
}

fn collect_text_recursive(node: NodeRef<Node>, acc: &mut String) {
    for child in node.children() {
        match child.value() {
            Node::Text(t) => {
                acc.push_str(t);
            }
            Node::Element(el) => {
                // Avoid extracting text from action panels or SVGs in sample code blocks
                if el.name() == "script" || el.name() == "style" || el.name() == "svg" {
                    continue;
                }
                collect_text_recursive(child, acc);
            }
            _ => {}
        }
    }
}

/// Iterates over sibling nodes and parses them into block elements.
/// Consecutive inline-level tags are automatically grouped into Paragraph blocks.
fn parse_block_nodes<'a, I>(nodes: I) -> Vec<ContentBlock>
where
    I: IntoIterator<Item = NodeRef<'a, Node>>,
{
    let mut blocks = Vec::new();
    let mut current_paragraph_inlines = Vec::new();

    let mut flush_paragraph = |inlines: &mut Vec<InlineNode>, blocks: &mut Vec<ContentBlock>| {
        if !inlines.is_empty() {
            // Only add if there is actual non-empty content
            let has_non_whitespace_content = inlines.iter().any(|node| match node {
                InlineNode::Text { text } => !text.trim().is_empty(),
                _ => true,
            });
            if has_non_whitespace_content {
                blocks.push(ContentBlock::Paragraph {
                    children: inlines.clone(),
                });
            }
            inlines.clear();
        }
    };

    for node in nodes {
        match node.value() {
            Node::Text(text_node) => {
                let text = text_node.to_string();
                if text.trim().is_empty() && current_paragraph_inlines.is_empty() {
                    continue;
                }
                current_paragraph_inlines.push(InlineNode::Text { text });
            }
            Node::Element(element) => {
                let tag_name = element.name();
                if is_block_element(tag_name) {
                    flush_paragraph(&mut current_paragraph_inlines, &mut blocks);

                    match tag_name {
                        "p" => {
                            let children = parse_inline_nodes(node.children());
                            blocks.push(ContentBlock::Paragraph { children });
                        }
                        "h1" | "h2" | "h3" | "h4" | "h5" | "h6" => {
                            let level = tag_name[1..].parse::<u8>().unwrap_or(1);
                            let children = parse_inline_nodes(node.children());
                            blocks.push(ContentBlock::Heading { level, children });
                        }
                        "img" => {
                            let url = element.attr("src").unwrap_or("").to_string();
                            let alt = element.attr("alt").map(|s| s.to_string());
                            blocks.push(ContentBlock::Image { url, alt });
                        }
                        "ul" | "ol" => {
                            let ordered = tag_name == "ol";
                            let mut items = Vec::new();
                            for child in node.children() {
                                if let Node::Element(child_el) = child.value() {
                                    if child_el.name() == "li" {
                                        let children = parse_inline_nodes(child.children());
                                        items.push(ListItem::Item { children });
                                    }
                                }
                            }
                            blocks.push(ContentBlock::List { ordered, items });
                        }
                        "table" => {
                            let mut rows = Vec::new();
                            let mut tr_nodes = Vec::new();
                            find_trs(node, &mut tr_nodes);

                            for tr_node in tr_nodes {
                                let mut cells = Vec::new();
                                for cell_node in tr_node.children() {
                                    if let Node::Element(cell_el) = cell_node.value() {
                                        if cell_el.name() == "td" || cell_el.name() == "th" {
                                            let children = parse_inline_nodes(cell_node.children());
                                            cells.push(TableCell::Cell { children });
                                        }
                                    }
                                }
                                rows.push(TableRow::Row { cells });
                            }
                            blocks.push(ContentBlock::Table { rows });
                        }
                        "blockquote" => {
                            let children = parse_inline_nodes(node.children());
                            blocks.push(ContentBlock::Quote { children });
                        }
                        "hr" => {
                            blocks.push(ContentBlock::Divider);
                        }
                        "pre" => {
                            let mut code_node = None;
                            for child in node.children() {
                                if let Node::Element(child_el) = child.value() {
                                    if child_el.name() == "code" {
                                        code_node = Some(child);
                                        break;
                                    }
                                }
                            }

                            let language = element
                                .attr("class")
                                .and_then(extract_language)
                                .or_else(|| {
                                    code_node.and_then(|cn| {
                                        if let Node::Element(el) = cn.value() {
                                            el.attr("class").and_then(extract_language)
                                        } else {
                                            None
                                        }
                                    })
                                });

                            let code = if let Some(cn) = code_node {
                                collect_text(cn)
                            } else {
                                collect_text(node)
                            };

                            blocks.push(ContentBlock::CodeBlock { language, code });
                        }
                        "div" => {
                            let classes = element.attr("class").unwrap_or("");
                            let is_highlight = classes.split_whitespace().any(|c| c == "highlight");

                            let mut pre_node = None;
                            if is_highlight {
                                for child in node.children() {
                                    if let Node::Element(child_el) = child.value() {
                                        if child_el.name() == "pre" {
                                            pre_node = Some(child);
                                            break;
                                        }
                                    }
                                }
                            }

                            if let Some(pre) = pre_node {
                                let mut language = None;
                                if let Node::Element(pre_el) = pre.value() {
                                    language = pre_el.attr("class").and_then(extract_language);
                                }
                                if language.is_none() {
                                    language = element.attr("class").and_then(extract_language);
                                }

                                let mut code_node = None;
                                for child in pre.children() {
                                    if let Node::Element(child_el) = child.value() {
                                        if child_el.name() == "code" {
                                            code_node = Some(child);
                                            break;
                                        }
                                    }
                                }

                                if language.is_none() {
                                    if let Some(cn) = code_node {
                                        if let Node::Element(el) = cn.value() {
                                            language = el.attr("class").and_then(extract_language);
                                        }
                                    }
                                }

                                let code = if let Some(cn) = code_node {
                                    collect_text(cn)
                                } else {
                                    collect_text(pre)
                                };

                                blocks.push(ContentBlock::CodeBlock { language, code });
                            } else {
                                let inner_blocks = parse_block_nodes(node.children());
                                blocks.extend(inner_blocks);
                            }
                        }
                        _ => {
                            let inner_blocks = parse_block_nodes(node.children());
                            blocks.extend(inner_blocks);
                        }
                    }
                } else {
                    let parsed_inlines = parse_inline_node(node);
                    current_paragraph_inlines.extend(parsed_inlines);
                }
            }
            _ => {}
        }
    }

    flush_paragraph(&mut current_paragraph_inlines, &mut blocks);

    blocks
}

/// Parses an iterator of nodes into a list of InlineNodes.
fn parse_inline_nodes<'a, I>(nodes: I) -> Vec<InlineNode>
where
    I: IntoIterator<Item = NodeRef<'a, Node>>,
{
    let mut inlines = Vec::new();
    for node in nodes {
        inlines.extend(parse_inline_node(node));
    }
    inlines
}

/// Helper function that maps individual DOM nodes to InlineNode variants.
fn parse_inline_node(node: NodeRef<Node>) -> Vec<InlineNode> {
    match node.value() {
        Node::Text(t) => {
            let text = t.to_string();
            vec![InlineNode::Text { text }]
        }
        Node::Element(el) => {
            let tag_name = el.name();
            match tag_name {
                "strong" | "b" => {
                    let children = parse_inline_nodes(node.children());
                    vec![InlineNode::Bold { children }]
                }
                "em" | "i" => {
                    let children = parse_inline_nodes(node.children());
                    vec![InlineNode::Italic { children }]
                }
                "a" => {
                    let url = el.attr("href").unwrap_or("").to_string();
                    let children = parse_inline_nodes(node.children());
                    vec![InlineNode::Link { url, children }]
                }
                "code" => {
                    let text = collect_text(node);
                    vec![InlineNode::InlineCode { text }]
                }
                "br" => {
                    vec![InlineNode::Break]
                }
                _ => parse_inline_nodes(node.children()),
            }
        }
        _ => Vec::new(),
    }
}

