//! # html-to-json parser
//!
//! Parses arbitrary HTML content into a structured, serialisable JSON tree.
//!
//! ## Quick start
//!
//! ```rust
//! use rust_rn_inte_prep::{parse_html, ContentBlock};
//!
//! let blocks: Vec<ContentBlock> = parse_html("<p>Hello <strong>world</strong></p>");
//! let json = serde_json::to_string_pretty(&blocks).unwrap();
//! println!("{json}");
//! ```
//!
//! ## Supported HTML elements
//!
//! | Element | Output type |
//! |---------|-------------|
//! | `<p>` | [`ContentBlock::Paragraph`] |
//! | `<h1>`–`<h6>` | [`ContentBlock::Heading`] |
//! | `<img>` | [`ContentBlock::Image`] |
//! | `<figure>` + `<figcaption>` | [`ContentBlock::Figure`] |
//! | `<pre><code>` | [`ContentBlock::CodeBlock`] |
//! | `<ul>` / `<ol>` (with nested lists) | [`ContentBlock::List`] |
//! | `<dl>` / `<dt>` / `<dd>` | [`ContentBlock::DefinitionList`] |
//! | `<table>` | [`ContentBlock::Table`] |
//! | `<blockquote>` | [`ContentBlock::Quote`] |
//! | `<video>` | [`ContentBlock::Video`] |
//! | `<audio>` | [`ContentBlock::Audio`] |
//! | `<iframe>` | [`ContentBlock::Embed`] |
//! | `<hr>` | [`ContentBlock::Divider`] |
//! | `<strong>` / `<b>` | [`InlineNode::Bold`] |
//! | `<em>` / `<i>` | [`InlineNode::Italic`] |
//! | `<a>` | [`InlineNode::Link`] |
//! | `<code>` (inline) | [`InlineNode::InlineCode`] |
//! | `<br>` | [`InlineNode::Break`] |

pub mod models;
pub mod parser;

// ── Flat re-exports for library consumers ────────────────────────────────────

/// Parse a fragment or full document of HTML into a `Vec<ContentBlock>`.
///
/// This is the primary entry point for the library.
///
/// ```rust
/// use rust_rn_inte_prep::parse_html;
///
/// let blocks = parse_html("<h1>Title</h1><p>Body text.</p>");
/// assert_eq!(blocks.len(), 2);
/// ```
pub use parser::html::parse_html;

// All public model types re-exported at the crate root for convenience.
pub use models::articles::{
    ContentBlock,
    DefinitionItem,
    InlineNode,
    ListItem,
    TableCell,
    TableRow,
};

use serde::Serialize;

/// A top-level content node that represents a single structural element of an HTML document.
///
/// Each variant maps directly to one or more HTML tags. The tree can be serialised
/// to JSON via [`serde_json`] because every type derives [`Serialize`].
#[derive(Debug, Clone, Serialize)]
pub enum ContentBlock {
    /// A `<p>` element or a run of bare inline content at the block level.
    Paragraph {
        children: Vec<InlineNode>,
    },

    /// A `<h1>`–`<h6>` heading element. `level` is 1–6.
    Heading {
        level: u8,
        children: Vec<InlineNode>,
    },

    /// A standalone `<img>` element (not inside a `<figure>`).
    Image {
        url: String,
        alt: Option<String>,
    },

    /// A `<figure>` element that wraps an image with an optional `<figcaption>`.
    Figure {
        url: String,
        alt: Option<String>,
        caption: Option<String>,
    },

    /// A fenced code block — either `<pre><code>` or a `<div class="highlight">` wrapper.
    CodeBlock {
        /// Detected programming language (e.g. `"typescript"`, `"bash"`), if any.
        language: Option<String>,
        /// Raw source code text with all HTML markup stripped.
        code: String,
    },

    /// An ordered (`<ol>`) or unordered (`<ul>`) list.
    /// Each [`ListItem`] may itself contain nested sub-lists.
    List {
        ordered: bool,
        items: Vec<ListItem>,
    },

    /// A `<table>` element with one or more rows.
    Table {
        rows: Vec<TableRow>,
    },

    /// A `<blockquote>` element.
    ///
    /// Unlike [`Paragraph`], the children here are full [`ContentBlock`]s,
    /// so `<p>` tags inside a blockquote are faithfully represented.
    Quote {
        children: Vec<ContentBlock>,
    },

    /// A `<dl>` definition list — a sequence of term / definition pairs.
    DefinitionList {
        items: Vec<DefinitionItem>,
    },

    /// A `<video>` element.
    Video {
        src: String,
        /// Optional thumbnail image URL (`poster` attribute).
        poster: Option<String>,
    },

    /// An `<audio>` element.
    Audio {
        src: String,
    },

    /// An `<iframe>` embed (YouTube, CodePen, etc.).
    Embed {
        src: String,
        title: Option<String>,
    },

    /// A `<hr>` horizontal rule / thematic break.
    Divider,
}

/// An inline-level content node that lives inside a block element's `children` list.
#[derive(Debug, Clone, Serialize)]
pub enum InlineNode {
    /// Plain text content.
    Text {
        text: String,
    },

    /// `<strong>` or `<b>` — bold text with recursive inline children.
    Bold {
        children: Vec<InlineNode>,
    },

    /// `<em>` or `<i>` — italic text with recursive inline children.
    Italic {
        children: Vec<InlineNode>,
    },

    /// `<a href="…">` hyperlink.
    Link {
        url: String,
        children: Vec<InlineNode>,
    },

    /// Inline `<code>` snippet (not a fenced block).
    InlineCode {
        text: String,
    },

    /// `<br>` line break.
    Break,
}

/// A single `<li>` item inside a [`ContentBlock::List`].
///
/// `children` contains the inline text of the list item.
/// `nested` contains any nested `<ul>` or `<ol>` found **inside** the same `<li>`.
#[derive(Debug, Clone, Serialize)]
pub enum ListItem {
    Item {
        children: Vec<InlineNode>,
        /// Nested sub-lists (each is a [`ContentBlock::List`]).
        nested: Vec<ContentBlock>,
    },
}

/// A `<dt>` / `<dd>` pair from a [`ContentBlock::DefinitionList`].
#[derive(Debug, Clone, Serialize)]
pub struct DefinitionItem {
    /// The term (`<dt>`).
    pub term: Vec<InlineNode>,
    /// The definition (`<dd>`).
    pub definition: Vec<InlineNode>,
}

/// A single row inside a [`ContentBlock::Table`].
#[derive(Debug, Clone, Serialize)]
pub enum TableRow {
    Row {
        cells: Vec<TableCell>,
    },
}

/// A single cell (`<td>` or `<th>`) inside a [`TableRow`].
#[derive(Debug, Clone, Serialize)]
pub enum TableCell {
    Cell {
        children: Vec<InlineNode>,
    },
}

// This binary is a quick sanity-check demo.
// As a library consumer you would instead add this crate to your Cargo.toml
// and call `rust_rn_inte_prep::parse_html(your_html_string)`.

use rust_rn_inte_prep::parse_html;

fn main() {
    let html = r#"
<h1>Hello world</h1>

<p>This parser turns <strong>any</strong> HTML into structured JSON.</p>

<blockquote>
  <p>First paragraph inside the quote.</p>
  <p>Second paragraph inside the quote.</p>
</blockquote>

<ul>
  <li>Top-level item
    <ul>
      <li>Nested A</li>
      <li>Nested B</li>
    </ul>
  </li>
  <li>Another item</li>
</ul>

<dl>
  <dt>Rust</dt>
  <dd>Systems language focused on safety.</dd>
</dl>

<figure>
  <img src="/img/demo.png" alt="Demo" />
  <figcaption>A demo image</figcaption>
</figure>

<pre class="language-rust"><code>fn main() {
    println!("Hello, world!");
}</code></pre>

<video src="/media/demo.mp4" poster="/media/thumb.jpg"></video>
<audio><source src="/media/track.mp3" /></audio>
<iframe src="https://www.youtube.com/embed/abc" title="Demo"></iframe>

<hr />
"#;

    let blocks = parse_html(html);
    let json = serde_json::to_string_pretty(&blocks).expect("serialisation failed");
    println!("{json}");
}

