use crate::models::{
    ContentBlock, DefinitionItem, InlineNode, ListItem, TableCell, TableRow,
};
use ego_tree::NodeRef;
use scraper::{Html, Node, Selector};

// ─────────────────────────────────────────────────────────────────────────────
// Public entry point
// ─────────────────────────────────────────────────────────────────────────────

/// Parse a fragment or full document of HTML into a `Vec<ContentBlock>`.
///
/// Handles both `Html::parse_fragment` output (which wraps content in a virtual
/// `<html><body>`) and raw root nodes as a fallback.
///
/// # Example
/// ```rust
/// use html_2_json::parse_html;
///
/// let blocks = parse_html("<h1>Title</h1><p>Body</p>");
/// assert_eq!(blocks.len(), 2);
/// ```
pub fn parse_html(html: &str) -> Vec<ContentBlock> {
    let html_dom = Html::parse_fragment(html);
    let body_selector = Selector::parse("body").unwrap();

    if let Some(body) = html_dom.select(&body_selector).next() {
        parse_block_nodes(body.children())
    } else {
        let root = html_dom.tree.root();
        if let Some(html_node) = root.first_child() {
            parse_block_nodes(html_node.children())
        } else {
            parse_block_nodes(root.children())
        }
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// Block-element classification
// ─────────────────────────────────────────────────────────────────────────────

/// Returns `true` for any tag that should be treated as a block-level element.
///
/// `tr`, `td`, `th`, `li`, `dt`, `dd` are listed here so they are **not**
/// mistaken for inline content when encountered outside their parent context.
/// They are consumed by their parent arm (`table` → tr/td/th, `ul`/`ol` → li,
/// `dl` → dt/dd).
fn is_block_element(name: &str) -> bool {
    matches!(
        name,
        "p" | "h1"
            | "h2"
            | "h3"
            | "h4"
            | "h5"
            | "h6"
            | "img"
            | "figure"
            | "ul"
            | "ol"
            | "li"
            | "dl"
            | "dt"
            | "dd"
            | "table"
            | "tr"
            | "td"
            | "th"
            | "blockquote"
            | "hr"
            | "pre"
            | "div"
            | "video"
            | "audio"
            | "iframe"
            | "section"
            | "article"
            | "header"
            | "footer"
            | "aside"
            | "nav"
    )
}

// ─────────────────────────────────────────────────────────────────────────────
// Helper: recursively collect all <tr> nodes under a table
// ─────────────────────────────────────────────────────────────────────────────

fn find_trs<'a>(node: NodeRef<'a, Node>, trs: &mut Vec<NodeRef<'a, Node>>) {
    for child in node.children() {
        if let Node::Element(el) = child.value() {
            match el.name() {
                "tr" => trs.push(child),
                "thead" | "tbody" | "tfoot" => find_trs(child, trs),
                _ => {}
            }
        }
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// Helper: attribute sanitisation
// ─────────────────────────────────────────────────────────────────────────────

/// Strips leading/trailing backslashes and quotes from an HTML attribute value.
/// Needed because scraper can return attribute values with backslash-escaped
/// quotes when the source HTML itself contains them.
fn clean_attribute(val: &str) -> String {
    val.trim_matches(|c| c == '\\' || c == '"' || c == '\'')
        .to_string()
}

// ─────────────────────────────────────────────────────────────────────────────
// Helper: language detection for code blocks
// ─────────────────────────────────────────────────────────────────────────────

/// Detect a programming language from a `class` attribute string.
/// Only returns a value when a `language-` or `lang-` prefix is found.
fn extract_language(class_str: &str) -> Option<String> {
    let cleaned = class_str.trim_matches(|c| c == '\\' || c == '"' || c == '\'');
    for part in cleaned.split_whitespace() {
        let p = part.trim_matches(|c| c == '\\' || c == '"' || c == '\'');
        if let Some(lang) = p.strip_prefix("language-") {
            return Some(lang.to_string());
        }
        if let Some(lang) = p.strip_prefix("lang-") {
            return Some(lang.to_string());
        }
    }
    None
}

/// Comprehensive list of well-known programming / markup language identifiers.
const KNOWN_LANGUAGES: &[&str] = &[
    "typescript", "javascript", "tsx", "jsx",
    "rust", "python", "go", "java", "kotlin", "swift",
    "c", "cpp", "csharp", "ruby", "php", "scala",
    "haskell", "elixir", "erlang", "clojure", "lua",
    "dart", "r", "julia",
    "bash", "sh", "zsh", "fish", "powershell",
    "sql", "html", "css", "scss", "sass", "less",
    "json", "yaml", "toml", "xml", "markdown",
    "plaintext", "text", "diff", "graphql",
    "dockerfile", "makefile", "nginx", "apache",
    "vim", "asm",
];

/// Try every available signal on the element to identify the programming language:
/// 1. `class` attribute with `language-*` or `lang-*` prefix (standard).
/// 2. Attribute *names* checked against `KNOWN_LANGUAGES` (for malformed HTML).
/// 3. Attribute *values* checked against `KNOWN_LANGUAGES`.
fn extract_language_from_element(element: &scraper::node::Element) -> Option<String> {
    // 1. Standard class-based detection
    if let Some(class_str) = element.attr("class") {
        if let Some(lang) = extract_language(class_str) {
            return Some(lang);
        }
    }
    // 2. Attribute name as language (some renderers emit `<pre typescript>`)
    for (name, _) in element.attrs() {
        let cleaned = name.trim_matches(|c| c == '\\' || c == '"' || c == '\'');
        if KNOWN_LANGUAGES.contains(&cleaned) {
            return Some(cleaned.to_string());
        }
    }
    // 3. Attribute value as language
    for (_, value) in element.attrs() {
        let cleaned = value.trim_matches(|c| c == '\\' || c == '"' || c == '\'');
        if KNOWN_LANGUAGES.contains(&cleaned) {
            return Some(cleaned.to_string());
        }
    }
    None
}

// ─────────────────────────────────────────────────────────────────────────────
// Helper: collect all text content from a subtree
// ─────────────────────────────────────────────────────────────────────────────

fn collect_text(node: NodeRef<Node>) -> String {
    let mut buf = String::new();
    collect_text_recursive(node, &mut buf);
    buf
}

fn collect_text_recursive(node: NodeRef<Node>, acc: &mut String) {
    for child in node.children() {
        match child.value() {
            Node::Text(t) => acc.push_str(&t),
            Node::Element(el) => {
                // Skip non-content noise inside code blocks
                if matches!(el.name(), "script" | "style" | "svg") {
                    continue;
                }
                collect_text_recursive(child, acc);
            }
            _ => {}
        }
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// Block parser
// ─────────────────────────────────────────────────────────────────────────────

/// Iterates over a sequence of sibling nodes and maps them to [`ContentBlock`]s.
///
/// Consecutive inline-level siblings are automatically accumulated and flushed
/// as a [`ContentBlock::Paragraph`] when the next block-level sibling (or end
/// of input) is encountered.
fn parse_block_nodes<'a, I>(nodes: I) -> Vec<ContentBlock>
where
    I: IntoIterator<Item = NodeRef<'a, Node>>,
{
    let mut blocks: Vec<ContentBlock> = Vec::new();
    let mut pending_inlines: Vec<InlineNode> = Vec::new();

    // Flush any accumulated inline nodes as a Paragraph (skips whitespace-only).
    let flush = |pending: &mut Vec<InlineNode>, blocks: &mut Vec<ContentBlock>| {
        if pending.is_empty() {
            return;
        }
        let has_content = pending.iter().any(|n| match n {
            InlineNode::Text { text } => !text.trim().is_empty(),
            _ => true,
        });
        if has_content {
            blocks.push(ContentBlock::Paragraph {
                children: pending.clone(),
            });
        }
        pending.clear();
    };

    for node in nodes {
        match node.value() {
            // ── Bare text nodes ───────────────────────────────────────────────
            Node::Text(t) => {
                let text = t.to_string();
                if text.trim().is_empty() && pending_inlines.is_empty() {
                    continue; // skip inter-block whitespace
                }
                pending_inlines.push(InlineNode::Text { text });
            }

            // ── Element nodes ─────────────────────────────────────────────────
            Node::Element(element) => {
                let tag = element.name();

                if is_block_element(tag) {
                    flush(&mut pending_inlines, &mut blocks);

                    match tag {
                        // ── Paragraph ─────────────────────────────────────────
                        "p" => {
                            let children = parse_inline_nodes(node.children());
                            blocks.push(ContentBlock::Paragraph { children });
                        }

                        // ── Headings ──────────────────────────────────────────
                        "h1" | "h2" | "h3" | "h4" | "h5" | "h6" => {
                            let level = tag[1..].parse::<u8>().unwrap_or(1);
                            let children = parse_inline_nodes(node.children());
                            blocks.push(ContentBlock::Heading { level, children });
                        }

                        // ── Standalone image ──────────────────────────────────
                        "img" => {
                            let url = element
                                .attr("src")
                                .map(|s| clean_attribute(&s))
                                .unwrap_or_default();
                            let alt = element.attr("alt").map(|s| clean_attribute(&s));
                            blocks.push(ContentBlock::Image { url, alt });
                        }

                        // ── Figure (image + optional caption) ─────────────────
                        "figure" => {
                            let mut url = String::new();
                            let mut alt: Option<String> = None;
                            let mut caption: Option<String> = None;

                            for child in node.children() {
                                if let Node::Element(el) = child.value() {
                                    match el.name() {
                                        "img" => {
                                            url = el
                                                .attr("src")
                                                .map(|s| clean_attribute(&s))
                                                .unwrap_or_default();
                                            alt = el.attr("alt").map(|s| clean_attribute(&s));
                                        }
                                        "figcaption" => {
                                            let text = collect_text(child).trim().to_string();
                                            if !text.is_empty() {
                                                caption = Some(text);
                                            }
                                        }
                                        _ => {}
                                    }
                                }
                            }
                            blocks.push(ContentBlock::Figure { url, alt, caption });
                        }

                        // ── Lists — supports nested lists inside <li> ──────────
                        "ul" | "ol" => {
                            let ordered = tag == "ol";
                            let items = parse_list_items(node);
                            blocks.push(ContentBlock::List { ordered, items });
                        }

                        // ── Definition list ───────────────────────────────────
                        "dl" => {
                            let items = parse_definition_list(node);
                            blocks.push(ContentBlock::DefinitionList { items });
                        }

                        // ── Table ─────────────────────────────────────────────
                        "table" => {
                            let mut tr_nodes = Vec::new();
                            find_trs(node, &mut tr_nodes);
                            let rows = tr_nodes
                                .into_iter()
                                .map(|tr| {
                                    let cells = tr
                                        .children()
                                        .filter_map(|cell| {
                                            if let Node::Element(el) = cell.value() {
                                                if matches!(el.name(), "td" | "th") {
                                                    let children =
                                                        parse_inline_nodes(cell.children());
                                                    return Some(TableCell::Cell { children });
                                                }
                                            }
                                            None
                                        })
                                        .collect();
                                    TableRow::Row { cells }
                                })
                                .collect();
                            blocks.push(ContentBlock::Table { rows });
                        }

                        // ── Blockquote — full block children ──────────────────
                        "blockquote" => {
                            let children = parse_block_nodes(node.children());
                            blocks.push(ContentBlock::Quote { children });
                        }

                        // ── Divider ───────────────────────────────────────────
                        "hr" => {
                            blocks.push(ContentBlock::Divider);
                        }

                        // ── Bare <pre><code> block ────────────────────────────
                        "pre" => {
                            // Find the inner <code> node for language detection
                            let code_child = node.children().find(|c| {
                                matches!(c.value(), Node::Element(el) if el.name() == "code")
                            });

                            let language = extract_language_from_element(element).or_else(|| {
                                code_child.and_then(|cn| {
                                    if let Node::Element(el) = cn.value() {
                                        extract_language_from_element(el)
                                    } else {
                                        None
                                    }
                                })
                            });

                            // Re-scan to collect text (avoids move after language check)
                            let code = node
                                .children()
                                .find(|c| {
                                    matches!(c.value(), Node::Element(el) if el.name() == "code")
                                })
                                .map(collect_text)
                                .unwrap_or_else(|| collect_text(node));

                            blocks.push(ContentBlock::CodeBlock { language, code });
                        }

                        // ── <div class="highlight"> code block ────────────────
                        "div" => {
                            let classes = element.attr("class").unwrap_or("");
                            let is_highlight = classes.split_whitespace().any(|c| {
                                c.trim_matches(|ch| ch == '\\' || ch == '"' || ch == '\'')
                                    == "highlight"
                            });

                            if is_highlight {
                                if let Some(pre) = node.children().find(|c| {
                                    matches!(c.value(), Node::Element(el) if el.name() == "pre")
                                }) {
                                    let language = if let Node::Element(pre_el) = pre.value() {
                                        extract_language_from_element(pre_el)
                                    } else {
                                        None
                                    }
                                    .or_else(|| extract_language_from_element(element))
                                    .or_else(|| {
                                        pre.children()
                                            .find(|c| {
                                                matches!(c.value(),
                                                    Node::Element(el) if el.name() == "code")
                                            })
                                            .and_then(|cn| {
                                                if let Node::Element(el) = cn.value() {
                                                    extract_language_from_element(el)
                                                } else {
                                                    None
                                                }
                                            })
                                    });

                                    let code = pre
                                        .children()
                                        .find(|c| {
                                            matches!(c.value(),
                                                Node::Element(el) if el.name() == "code")
                                        })
                                        .map(collect_text)
                                        .unwrap_or_else(|| collect_text(pre));

                                    blocks.push(ContentBlock::CodeBlock { language, code });
                                } else {
                                    blocks.extend(parse_block_nodes(node.children()));
                                }
                            } else {
                                // Generic div — recurse into children
                                blocks.extend(parse_block_nodes(node.children()));
                            }
                        }

                        // ── Video ─────────────────────────────────────────────
                        "video" => {
                            let src = element
                                .attr("src")
                                .map(|s| clean_attribute(&s))
                                .or_else(|| {
                                    node.children().find_map(|c| {
                                        if let Node::Element(el) = c.value() {
                                            if el.name() == "source" {
                                                return el
                                                    .attr("src")
                                                    .map(|s| clean_attribute(&s));
                                            }
                                        }
                                        None
                                    })
                                })
                                .unwrap_or_default();

                            let poster = element.attr("poster").map(|s| clean_attribute(&s));
                            blocks.push(ContentBlock::Video { src, poster });
                        }

                        // ── Audio ─────────────────────────────────────────────
                        "audio" => {
                            let src = element
                                .attr("src")
                                .map(|s| clean_attribute(&s))
                                .or_else(|| {
                                    node.children().find_map(|c| {
                                        if let Node::Element(el) = c.value() {
                                            if el.name() == "source" {
                                                return el
                                                    .attr("src")
                                                    .map(|s| clean_attribute(&s));
                                            }
                                        }
                                        None
                                    })
                                })
                                .unwrap_or_default();

                            blocks.push(ContentBlock::Audio { src });
                        }

                        // ── Iframe embed ──────────────────────────────────────
                        "iframe" => {
                            let src = element
                                .attr("src")
                                .map(|s| clean_attribute(&s))
                                .unwrap_or_default();
                            let title = element.attr("title").map(|s| clean_attribute(&s));
                            blocks.push(ContentBlock::Embed { src, title });
                        }

                        // ── Generic container — recurse ───────────────────────
                        _ => {
                            blocks.extend(parse_block_nodes(node.children()));
                        }
                    }
                } else {
                    // Inline element at block level — accumulate into pending paragraph
                    pending_inlines.extend(parse_inline_node(node));
                }
            }

            _ => {}
        }
    }

    flush(&mut pending_inlines, &mut blocks);
    blocks
}

// ─────────────────────────────────────────────────────────────────────────────
// List item parser (handles nested <ul>/<ol> inside <li>)
// ─────────────────────────────────────────────────────────────────────────────

fn parse_list_items(list_node: NodeRef<Node>) -> Vec<ListItem> {
    let mut items = Vec::new();

    for child in list_node.children() {
        if let Node::Element(el) = child.value() {
            if el.name() == "li" {
                let mut inline_children: Vec<InlineNode> = Vec::new();
                let mut nested_blocks: Vec<ContentBlock> = Vec::new();

                for li_child in child.children() {
                    match li_child.value() {
                        Node::Element(li_el) => {
                            if matches!(li_el.name(), "ul" | "ol") {
                                // Nested list → becomes a nested ContentBlock::List
                                let ordered = li_el.name() == "ol";
                                let nested_items = parse_list_items(li_child);
                                nested_blocks.push(ContentBlock::List {
                                    ordered,
                                    items: nested_items,
                                });
                            } else {
                                inline_children.extend(parse_inline_node(li_child));
                            }
                        }
                        Node::Text(t) => {
                            inline_children.push(InlineNode::Text {
                                text: t.to_string(),
                            });
                        }
                        _ => {}
                    }
                }

                items.push(ListItem::Item {
                    children: inline_children,
                    nested: nested_blocks,
                });
            }
        }
    }

    items
}

// ─────────────────────────────────────────────────────────────────────────────
// Definition list parser
// ─────────────────────────────────────────────────────────────────────────────

fn parse_definition_list(dl_node: NodeRef<Node>) -> Vec<DefinitionItem> {
    let mut items: Vec<DefinitionItem> = Vec::new();
    let mut current_term: Option<Vec<InlineNode>> = None;

    for child in dl_node.children() {
        if let Node::Element(el) = child.value() {
            match el.name() {
                "dt" => {
                    current_term = Some(parse_inline_nodes(child.children()));
                }
                "dd" => {
                    let definition = parse_inline_nodes(child.children());
                    let term = current_term.take().unwrap_or_default();
                    items.push(DefinitionItem { term, definition });
                }
                _ => {}
            }
        }
    }

    items
}

// ─────────────────────────────────────────────────────────────────────────────
// Inline parser
// ─────────────────────────────────────────────────────────────────────────────

/// Parse all children of a node as inline content.
fn parse_inline_nodes<'a, I>(nodes: I) -> Vec<InlineNode>
where
    I: IntoIterator<Item = NodeRef<'a, Node>>,
{
    nodes.into_iter().flat_map(parse_inline_node).collect()
}

/// Map a single DOM node to zero or more [`InlineNode`]s.
fn parse_inline_node(node: NodeRef<Node>) -> Vec<InlineNode> {
    match node.value() {
        Node::Text(t) => vec![InlineNode::Text {
            text: t.to_string(),
        }],

        Node::Element(el) => match el.name() {
            "strong" | "b" => vec![InlineNode::Bold {
                children: parse_inline_nodes(node.children()),
            }],

            "em" | "i" => vec![InlineNode::Italic {
                children: parse_inline_nodes(node.children()),
            }],

            "a" => vec![InlineNode::Link {
                url: el
                    .attr("href")
                    .map(|s| clean_attribute(&s))
                    .unwrap_or_default(),
                children: parse_inline_nodes(node.children()),
            }],

            "code" => vec![InlineNode::InlineCode {
                text: collect_text(node),
            }],

            "br" => vec![InlineNode::Break],

            // Any other inline wrapper (span, abbr, mark, …) — recurse into children
            _ => parse_inline_nodes(node.children()),
        },

        _ => Vec::new(),
    }
}

//! # html_2_json
//!
//! Parse arbitrary HTML content into a structured, serialisable JSON tree.
//!
//! ## Quick start
//!
//! ```rust
//! use html_2_json::{parse_html, ContentBlock};
//!
//! let blocks: Vec<ContentBlock> = parse_html("<p>Hello <strong>world</strong></p>");
//! let json = serde_json::to_string_pretty(&blocks).unwrap();
//! println!("{json}");
//! ```
//!
//! ## Supported HTML elements
//!
//! | Element | Output type |
//! |---------|-------------|
//! | `<p>` | [`ContentBlock::Paragraph`] |
//! | `<h1>`–`<h6>` | [`ContentBlock::Heading`] |
//! | `<img>` | [`ContentBlock::Image`] |
//! | `<figure>` + `<figcaption>` | [`ContentBlock::Figure`] |
//! | `<pre><code>` / `<div class="highlight">` | [`ContentBlock::CodeBlock`] |
//! | `<ul>` / `<ol>` (with nested lists) | [`ContentBlock::List`] |
//! | `<dl>` / `<dt>` / `<dd>` | [`ContentBlock::DefinitionList`] |
//! | `<table>` | [`ContentBlock::Table`] |
//! | `<blockquote>` | [`ContentBlock::Quote`] |
//! | `<video>` | [`ContentBlock::Video`] |
//! | `<audio>` | [`ContentBlock::Audio`] |
//! | `<iframe>` | [`ContentBlock::Embed`] |
//! | `<hr>` | [`ContentBlock::Divider`] |
//! | `<strong>` / `<b>` | [`InlineNode::Bold`] |
//! | `<em>` / `<i>` | [`InlineNode::Italic`] |
//! | `<a>` | [`InlineNode::Link`] |
//! | `<code>` (inline) | [`InlineNode::InlineCode`] |
//! | `<br>` | [`InlineNode::Break`] |

mod models;
mod parser;

// ── Public API ────────────────────────────────────────────────────────────────

/// Parse a fragment or full document of HTML into a `Vec<ContentBlock>`.
///
/// This is the single entry point for the library.
///
/// ```rust
/// use html_2_json::parse_html;
///
/// let blocks = parse_html("<h1>Hello</h1><p>World</p>");
/// assert_eq!(blocks.len(), 2);
/// ```
pub use parser::parse_html;

// All public model types re-exported at the crate root.
pub use models::{
    ContentBlock,
    DefinitionItem,
    InlineNode,
    ListItem,
    TableCell,
    TableRow,
};

args.ReplacementContent:
            _ => parse_inline_nodes(node.children()),
        },

        _ => Vec::new(),
    }
}

// ─────────────────────────────────────────────────────────────────────────────
// Tests
// ─────────────────────────────────────────────────────────────────────────────

#[cfg(test)]
mod tests {
    use super::*;

    // ── helpers ───────────────────────────────────────────────────────────────

    fn text(s: &str) -> InlineNode {
        InlineNode::Text { text: s.to_string() }
    }

    fn only_block(html: &str) -> ContentBlock {
        let mut blocks = parse_html(html);
        assert_eq!(blocks.len(), 1, "expected 1 block, got {}: {blocks:#?}", blocks.len());
        blocks.remove(0)
    }

    // ── paragraph ─────────────────────────────────────────────────────────────

    #[test]
    fn test_paragraph_plain_text() {
        let block = only_block("<p>Hello world</p>");
        assert!(matches!(block, ContentBlock::Paragraph { .. }));
        if let ContentBlock::Paragraph { children } = block {
            assert_eq!(children.len(), 1);
            assert!(matches!(&children[0], InlineNode::Text { text } if text == "Hello world"));
        }
    }

    #[test]
    fn test_paragraph_with_bold_and_italic() {
        let block = only_block("<p><strong>bold</strong> and <em>italic</em></p>");
        if let ContentBlock::Paragraph { children } = block {
            assert!(matches!(&children[0], InlineNode::Bold { .. }));
            assert!(matches!(&children[2], InlineNode::Italic { .. }));
        } else {
            panic!("expected Paragraph");
        }
    }

    #[test]
    fn test_paragraph_with_link() {
        let block = only_block(r#"<p><a href="https://example.com">click</a></p>"#);
        if let ContentBlock::Paragraph { children } = block {
            assert!(matches!(&children[0], InlineNode::Link { url, .. } if url == "https://example.com"));
        } else {
            panic!("expected Paragraph");
        }
    }

    #[test]
    fn test_paragraph_with_inline_code() {
        let block = only_block("<p>Use <code>parse_html()</code></p>");
        if let ContentBlock::Paragraph { children } = block {
            assert!(matches!(&children[1], InlineNode::InlineCode { text } if text == "parse_html()"));
        } else {
            panic!("expected Paragraph");
        }
    }

    #[test]
    fn test_paragraph_with_line_break() {
        let block = only_block("<p>line1<br>line2</p>");
        if let ContentBlock::Paragraph { children } = block {
            assert!(children.iter().any(|n| matches!(n, InlineNode::Break)));
        } else {
            panic!("expected Paragraph");
        }
    }

    // ── headings ──────────────────────────────────────────────────────────────

    #[test]
    fn test_headings_level_1_to_6() {
        for lvl in 1u8..=6 {
            let html = format!("<h{lvl}>Heading {lvl}</h{lvl}>");
            let block = only_block(&html);
            assert!(
                matches!(block, ContentBlock::Heading { level, .. } if level == lvl),
                "h{lvl} failed"
            );
        }
    }

    // ── image ─────────────────────────────────────────────────────────────────

    #[test]
    fn test_standalone_image() {
        let block = only_block(r#"<img src="/img/photo.jpg" alt="A photo" />"#);
        assert!(matches!(
            block,
            ContentBlock::Image { url, alt }
            if url == "/img/photo.jpg" && alt == Some("A photo".to_string())
        ));
    }

    #[test]
    fn test_image_without_alt() {
        let block = only_block(r#"<img src="/img/x.png" />"#);
        assert!(matches!(block, ContentBlock::Image { alt: None, .. }));
    }

    // ── figure ────────────────────────────────────────────────────────────────

    #[test]
    fn test_figure_with_caption() {
        let block = only_block(r#"
            <figure>
              <img src="/img/fig.jpg" alt="Fig" />
              <figcaption>The caption</figcaption>
            </figure>
        "#);
        assert!(matches!(
            block,
            ContentBlock::Figure { url, alt, caption }
            if url == "/img/fig.jpg"
                && alt == Some("Fig".to_string())
                && caption == Some("The caption".to_string())
        ));
    }

    #[test]
    fn test_figure_without_caption() {
        let block = only_block(r#"<figure><img src="/img/fig.jpg" /></figure>"#);
        assert!(matches!(block, ContentBlock::Figure { caption: None, .. }));
    }

    // ── divider ───────────────────────────────────────────────────────────────

    #[test]
    fn test_divider() {
        let block = only_block("<hr />");
        assert!(matches!(block, ContentBlock::Divider));
    }

    // ── lists ─────────────────────────────────────────────────────────────────

    #[test]
    fn test_unordered_list() {
        let block = only_block("<ul><li>A</li><li>B</li></ul>");
        if let ContentBlock::List { ordered, items } = block {
            assert!(!ordered);
            assert_eq!(items.len(), 2);
        } else {
            panic!("expected List");
        }
    }

    #[test]
    fn test_ordered_list() {
        let block = only_block("<ol><li>First</li><li>Second</li></ol>");
        if let ContentBlock::List { ordered, items } = block {
            assert!(ordered);
            assert_eq!(items.len(), 2);
        } else {
            panic!("expected List");
        }
    }

    #[test]
    fn test_nested_list() {
        let block = only_block(r#"
            <ul>
              <li>Top
                <ul>
                  <li>Nested A</li>
                  <li>Nested B</li>
                </ul>
              </li>
            </ul>
        "#);
        if let ContentBlock::List { items, .. } = block {
            let ListItem::Item { nested, .. } = &items[0];
            assert_eq!(nested.len(), 1, "nested list missing");
            assert!(matches!(&nested[0], ContentBlock::List { items, .. } if items.len() == 2));
        } else {
            panic!("expected List");
        }
    }

    // ── blockquote ────────────────────────────────────────────────────────────

    #[test]
    fn test_blockquote_with_paragraphs() {
        let block = only_block(r#"
            <blockquote>
              <p>First</p>
              <p>Second</p>
            </blockquote>
        "#);
        if let ContentBlock::Quote { children } = block {
            assert_eq!(children.len(), 2, "blockquote should have 2 Paragraph children");
            assert!(matches!(&children[0], ContentBlock::Paragraph { .. }));
            assert!(matches!(&children[1], ContentBlock::Paragraph { .. }));
        } else {
            panic!("expected Quote");
        }
    }

    // ── definition list ───────────────────────────────────────────────────────

    #[test]
    fn test_definition_list() {
        let block = only_block(r#"
            <dl>
              <dt>Rust</dt>
              <dd>Systems language.</dd>
              <dt>Go</dt>
              <dd>Google language.</dd>
            </dl>
        "#);
        if let ContentBlock::DefinitionList { items } = block {
            assert_eq!(items.len(), 2);
            assert!(matches!(&items[0].term[0], InlineNode::Text { text } if text == "Rust"));
            assert!(matches!(&items[1].term[0], InlineNode::Text { text } if text == "Go"));
        } else {
            panic!("expected DefinitionList");
        }
    }

