// ─────────────────────────────────────────────────────────────────────────────
// Tests
// ─────────────────────────────────────────────────────────────────────────────

#[cfg(test)]
mod tests {
    use super::*;

    // ── helpers ───────────────────────────────────────────────────────────────


    fn only_block(html: &str) -> ContentBlock {
        let mut blocks = parse_html(html);
        assert_eq!(blocks.len(), 1, "expected 1 block, got {}: {blocks:#?}", blocks.len());
        blocks.remove(0)
    }

    // ── paragraph ─────────────────────────────────────────────────────────────

    #[test]
    fn test_paragraph_plain_text() {
        let block = only_block("<p>Hello world</p>");
        assert!(matches!(block, ContentBlock::Paragraph { .. }));
        if let ContentBlock::Paragraph { children } = block {
            assert_eq!(children.len(), 1);
            assert!(matches!(&children[0], InlineNode::Text { text } if text == "Hello world"));
        }
    }

    #[test]
    fn test_paragraph_with_bold_and_italic() {
        let block = only_block("<p><strong>bold</strong> and <em>italic</em></p>");
        if let ContentBlock::Paragraph { children } = block {
            assert!(matches!(&children[0], InlineNode::Bold { .. }));
            assert!(matches!(&children[2], InlineNode::Italic { .. }));
        } else {
            panic!("expected Paragraph");
        }
    }

    #[test]
    fn test_paragraph_with_link() {
        let block = only_block(r#"<p><a href="https://example.com">click</a></p>"#);
        if let ContentBlock::Paragraph { children } = block {
            assert!(matches!(&children[0], InlineNode::Link { url, .. } if url == "https://example.com"));
        } else {
            panic!("expected Paragraph");
        }
    }

    #[test]
    fn test_paragraph_with_inline_code() {
        let block = only_block("<p>Use <code>parse_html()</code></p>");
        if let ContentBlock::Paragraph { children } = block {
            assert!(matches!(&children[1], InlineNode::InlineCode { text } if text == "parse_html()"));
        } else {
            panic!("expected Paragraph");
        }
    }

    #[test]
    fn test_paragraph_with_line_break() {
        let block = only_block("<p>line1<br>line2</p>");
        if let ContentBlock::Paragraph { children } = block {
            assert!(children.iter().any(|n| matches!(n, InlineNode::Break)));
        } else {
            panic!("expected Paragraph");
        }
    }

    // ── headings ──────────────────────────────────────────────────────────────

    #[test]
    fn test_headings_level_1_to_6() {
        for lvl in 1u8..=6 {
            let html = format!("<h{lvl}>Heading {lvl}</h{lvl}>");
            let block = only_block(&html);
            assert!(
                matches!(block, ContentBlock::Heading { level, .. } if level == lvl),
                "h{lvl} failed"
            );
        }
    }

    // ── image ─────────────────────────────────────────────────────────────────

    #[test]
    fn test_standalone_image() {
        let block = only_block(r#"<img src="/img/photo.jpg" alt="A photo" />"#);
        assert!(matches!(
            block,
            ContentBlock::Image { url, alt }
            if url == "/img/photo.jpg" && alt == Some("A photo".to_string())
        ));
    }

    #[test]
    fn test_image_without_alt() {
        let block = only_block(r#"<img src="/img/x.png" />"#);
        assert!(matches!(block, ContentBlock::Image { alt: None, .. }));
    }

    // ── figure ────────────────────────────────────────────────────────────────

    #[test]
    fn test_figure_with_caption() {
        let block = only_block(r#"
            <figure>
              <img src="/img/fig.jpg" alt="Fig" />
              <figcaption>The caption</figcaption>
            </figure>
        "#);
        assert!(matches!(
            block,
            ContentBlock::Figure { url, alt, caption }
            if url == "/img/fig.jpg"
                && alt == Some("Fig".to_string())
                && caption == Some("The caption".to_string())
        ));
    }

    #[test]
    fn test_figure_without_caption() {
        let block = only_block(r#"<figure><img src="/img/fig.jpg" /></figure>"#);
        assert!(matches!(block, ContentBlock::Figure { caption: None, .. }));
    }

    // ── divider ───────────────────────────────────────────────────────────────

    #[test]
    fn test_divider() {
        let block = only_block("<hr />");
        assert!(matches!(block, ContentBlock::Divider));
    }

    // ── lists ─────────────────────────────────────────────────────────────────

    #[test]
    fn test_unordered_list() {
        let block = only_block("<ul><li>A</li><li>B</li></ul>");
        if let ContentBlock::List { ordered, items } = block {
            assert!(!ordered);
            assert_eq!(items.len(), 2);
        } else {
            panic!("expected List");
        }
    }

    #[test]
    fn test_ordered_list() {
        let block = only_block("<ol><li>First</li><li>Second</li></ol>");
        if let ContentBlock::List { ordered, items } = block {
            assert!(ordered);
            assert_eq!(items.len(), 2);
        } else {
            panic!("expected List");
        }
    }

    #[test]
    fn test_nested_list() {
        let block = only_block(r#"
            <ul>
              <li>Top
                <ul>
                  <li>Nested A</li>
                  <li>Nested B</li>
                </ul>
              </li>
            </ul>
        "#);
        if let ContentBlock::List { items, .. } = block {
            let ListItem::Item { nested, .. } = &items[0];
            assert_eq!(nested.len(), 1, "nested list missing");
            assert!(matches!(&nested[0], ContentBlock::List { items, .. } if items.len() == 2));
        } else {
            panic!("expected List");
        }
    }

    // ── blockquote ────────────────────────────────────────────────────────────

    #[test]
    fn test_blockquote_with_paragraphs() {
        let block = only_block(r#"
            <blockquote>
              <p>First</p>
              <p>Second</p>
            </blockquote>
        "#);
        if let ContentBlock::Quote { children } = block {
            assert_eq!(children.len(), 2, "blockquote should have 2 Paragraph children");
            assert!(matches!(&children[0], ContentBlock::Paragraph { .. }));
            assert!(matches!(&children[1], ContentBlock::Paragraph { .. }));
        } else {
            panic!("expected Quote");
        }
    }

    // ── definition list ───────────────────────────────────────────────────────

    #[test]
    fn test_definition_list() {
        let block = only_block(r#"
            <dl>
              <dt>Rust</dt>
              <dd>Systems language.</dd>
              <dt>Go</dt>
              <dd>Google language.</dd>
            </dl>
        "#);
        if let ContentBlock::DefinitionList { items } = block {
            assert_eq!(items.len(), 2);
            assert!(matches!(&items[0].term[0], InlineNode::Text { text } if text == "Rust"));
            assert!(matches!(&items[1].term[0], InlineNode::Text { text } if text == "Go"));
        } else {
            panic!("expected DefinitionList");
        }
    }

    // ── table ─────────────────────────────────────────────────────────────────

    #[test]
    fn test_table_rows_and_cells() {
        let block = only_block(r#"
            <table>
              <thead><tr><th>Name</th><th>Age</th></tr></thead>
              <tbody><tr><td>Alice</td><td>30</td></tr></tbody>
            </table>
        "#);
        if let ContentBlock::Table { rows } = block {
            assert_eq!(rows.len(), 2);
            let TableRow::Row { cells } = &rows[0];
            assert_eq!(cells.len(), 2);
        } else {
            panic!("expected Table");
        }
    }

    // ── code blocks ───────────────────────────────────────────────────────────

    #[test]
    fn test_pre_code_with_language_prefix() {
        let block = only_block(r#"<pre class="language-rust"><code>fn main() {}</code></pre>"#);
        assert!(matches!(
            block,
            ContentBlock::CodeBlock { language: Some(lang), .. }
            if lang == "rust"
        ));
    }

    #[test]
    fn test_pre_code_with_lang_prefix() {
        let block = only_block(r#"<pre class="lang-python"><code>print("hi")</code></pre>"#);
        assert!(matches!(
            block,
            ContentBlock::CodeBlock { language: Some(lang), .. }
            if lang == "python"
        ));
    }

    #[test]
    fn test_pre_code_language_on_inner_code_element() {
        let block = only_block(r#"<pre><code class="language-go">fmt.Println()</code></pre>"#);
        assert!(matches!(
            block,
            ContentBlock::CodeBlock { language: Some(lang), .. }
            if lang == "go"
        ));
    }

    #[test]
    fn test_pre_code_known_language_attr_name() {
        // Some renderers emit <pre typescript> instead of class="language-typescript"
        let block = only_block(r#"<pre typescript><code>const x = 1</code></pre>"#);
        assert!(matches!(
            block,
            ContentBlock::CodeBlock { language: Some(lang), .. }
            if lang == "typescript"
        ));
    }

    #[test]
    fn test_pre_code_no_language() {
        let block = only_block(r#"<pre><code>raw code</code></pre>"#);
        assert!(matches!(
            block,
            ContentBlock::CodeBlock { language: None, code }
            if code == "raw code"
        ));
    }

    #[test]
    fn test_div_highlight_code_block() {
        let html = r#"
            <div class="highlight">
              <pre class="highlight typescript"><code>const x = 1;</code></pre>
            </div>
        "#;
        let block = only_block(html);
        assert!(matches!(
            block,
            ContentBlock::CodeBlock { language: Some(lang), code }
            if lang == "typescript" && code == "const x = 1;"
        ));
    }

    #[test]
    fn test_code_text_strips_html_spans() {
        // The classic dev.to / GitHub syntax-highlighted code block
        let html = r#"<pre class="language-rust"><code><span class="k">fn</span> <span class="nf">main</span><span class="p">()</span> <span class="p">{}</span></code></pre>"#;
        let block = only_block(html);
        if let ContentBlock::CodeBlock { code, .. } = block {
            assert_eq!(code.trim(), "fn main() {}");
        } else {
            panic!("expected CodeBlock");
        }
    }

    // ── media embeds ──────────────────────────────────────────────────────────

    #[test]
    fn test_video_with_src_attr() {
        let block = only_block(r#"<video src="/v.mp4" poster="/thumb.jpg"></video>"#);
        assert!(matches!(
            block,
            ContentBlock::Video { src, poster }
            if src == "/v.mp4" && poster == Some("/thumb.jpg".to_string())
        ));
    }

    #[test]
    fn test_video_with_source_child() {
        let block = only_block(r#"<video><source src="/v.webm" /></video>"#);
        assert!(matches!(
            block,
            ContentBlock::Video { src, .. }
            if src == "/v.webm"
        ));
    }

    #[test]
    fn test_audio_with_source_child() {
        let block = only_block(r#"<audio><source src="/track.mp3" /></audio>"#);
        assert!(matches!(
            block,
            ContentBlock::Audio { src }
            if src == "/track.mp3"
        ));
    }

    #[test]
    fn test_iframe_embed() {
        let block = only_block(r#"<iframe src="https://www.youtube.com/embed/abc" title="Demo"></iframe>"#);
        assert!(matches!(
            block,
            ContentBlock::Embed { src, title }
            if src == "https://www.youtube.com/embed/abc"
                && title == Some("Demo".to_string())
        ));
    }

    // ── multiple blocks ───────────────────────────────────────────────────────

    #[test]
    fn test_multiple_blocks_preserved_in_order() {
        let blocks = parse_html("<h1>Title</h1><p>Body</p><hr />");
        assert_eq!(blocks.len(), 3);
        assert!(matches!(blocks[0], ContentBlock::Heading { level: 1, .. }));
        assert!(matches!(blocks[1], ContentBlock::Paragraph { .. }));
        assert!(matches!(blocks[2], ContentBlock::Divider));
    }

    #[test]
    fn test_empty_html_returns_empty_vec() {
        let blocks = parse_html("");
        assert!(blocks.is_empty());
    }

    #[test]
    fn test_whitespace_only_text_not_emitted_as_paragraph() {
        let blocks = parse_html("   \n   ");
        assert!(blocks.is_empty());
    }

    // ── inline-only input becomes a paragraph ─────────────────────────────────

    #[test]
    fn test_bare_inline_text_wrapped_in_paragraph() {
        let blocks = parse_html("just some text");
        assert_eq!(blocks.len(), 1);
        assert!(matches!(blocks[0], ContentBlock::Paragraph { .. }));
    }

    // ── attribute sanitisation ────────────────────────────────────────────────

    #[test]
    fn test_clean_attribute_strips_quotes_and_backslashes() {
        // clean_attribute is private but we can test it indirectly via image src
        let block = only_block(r#"<img src="/img/x.jpg" />"#);
        assert!(matches!(block, ContentBlock::Image { url, .. } if url == "/img/x.jpg"));
    }
}

