## ⚡ Step 4: Write the C++ JSI HostObjects

Inside `cpp/HTMLParserHostObjects.h`, we wrap our Rust pointer in a `jsi::HostObject`. We query the Rust FFI directly as properties are accessed in JavaScript.

```cpp
#pragma once
#include <jsi/jsi.h>

extern "C" {
    // Declarations matching ffi.rs
    struct ParsedArticle;
    ParsedArticle* parse_html_ffi(const char* html);
    void free_article_ffi(ParsedArticle* article);
    size_t get_block_count(const ParsedArticle* article);
    char* get_block_type(const ParsedArticle* article, size_t index);
    uint8_t get_heading_level(const ParsedArticle* article, size_t index);
    char* get_image_url(const ParsedArticle* article, size_t index);
    char* get_image_alt(const ParsedArticle* article, size_t index);
    char* get_codeblock_code(const ParsedArticle* article, size_t index);
    char* get_codeblock_lang(const ParsedArticle* article, size_t index);
    size_t get_block_child_count(const ParsedArticle* article, size_t index);
    void free_string_ffi(char* s);
}

using namespace facebook;

// HostObject representing a single ContentBlock
class BlockHostObject : public jsi::HostObject {
private:
    const ParsedArticle* m_article;
    size_t m_index;
    std::string m_type;

public:
    BlockHostObject(const ParsedArticle* article, size_t index, std::string type)
        : m_article(article), m_index(index), m_type(type) {}

    jsi::Value get(jsi::Runtime& rt, const jsi::PropNameID& name) override {
        auto propName = name.utf8(rt);

        if (propName == "type") {
            return jsi::String::createFromUtf8(rt, m_type);
        }

        // Paragraph/Heading children count
        if (propName == "childCount") {
            return jsi::Value((int)get_block_child_count(m_article, m_index));
        }

        // Heading level
        if (propName == "level" && m_type == "Heading") {
            return jsi::Value((int)get_heading_level(m_article, m_index));
        }

        // Image/Figure url
        if (propName == "url" && (m_type == "Image" || m_type == "Figure")) {
            char* raw_url = get_image_url(m_article, m_index);
            jsi::String jsUrl = jsi::String::createFromUtf8(rt, raw_url);
            free_string_ffi(raw_url);
            return jsUrl;
        }

        // CodeBlock source code
        if (propName == "code" && m_type == "CodeBlock") {
            char* raw_code = get_codeblock_code(m_article, m_index);
            jsi::String jsCode = jsi::String::createFromUtf8(rt, raw_code);
            free_string_ffi(raw_code);
            return jsCode;
        }

        return jsi::Value::undefined();
    }
};

// HostObject representing the entire parsed article array
class ArticleHostObject : public jsi::HostObject {
private:
    ParsedArticle* m_article;

public:
    ArticleHostObject(const char* html) {
        m_article = parse_html_ffi(html);
    }

    ~ArticleHostObject() {
        free_article_ffi(m_article);
    }

    jsi::Value get(jsi::Runtime& rt, const jsi::PropNameID& name) override {
        auto propName = name.utf8(rt);

        // article.length
        if (propName == "length") {
            return jsi::Value((int)get_block_count(m_article));
        }

        // article.getBlock(index)
        if (propName == "getBlock") {
            return jsi::Function::createFromHostFunction(
                rt, name, 1,
                [this](jsi::Runtime& rt, const jsi::Value& thisVal, const jsi::Value* args, size_t count) -> jsi::Value {
                    size_t index = args[0].asNumber();

                    char* raw_type = get_block_type(m_article, index);
                    std::string typeStr(raw_type);
                    free_string_ffi(raw_type);

                    // Returns a new BlockHostObject wrapping the index
                    return jsi::Object::createFromHostObject(
                        rt, std::make_shared<BlockHostObject>(m_article, index, typeStr)
                    );
                }
            );
        }

        return jsi::Value::undefined();
    }
};
```

